<script setup lang="ts">
import {ref,watch} from 'vue'
import type {Listing} from './listingTypes'
const props=defineProps<{row:Listing|null}>(),emit=defineEmits<{close:[],calculated:[value:any]}>()
const price=ref(''),busy=ref(false),error=ref(''),result=ref<any>(null)
let generation=0
watch(()=>props.row,row=>{generation++;result.value=null;error.value='';price.value='';busy.value=false;if(row)calculate(false)})
async function calculate(custom=true){
 const row=props.row;if(!row)return
 if(custom&&(!/^\d+(\.\d{1,2})?$/.test(price.value)||Number(price.value)<=0)){error.value='请输入大于0、最多两位小数的售价';return}
 const id=++generation;busy.value=true;error.value='';result.value=null
 try{const r=await fetch(`/api/listings/${row.id}/income-estimate`,{method:'POST',headers:{'Content-Type':'application/json','X-ERP-Client':'web'},body:JSON.stringify(custom?{price:price.value}:{})});const d=await r.json();if(!r.ok)throw new Error(typeof d.detail==='string'?d.detail:'费用读取失败');if(id!==generation)return;result.value=d;price.value=d.price;emit('calculated',d)}catch(e){if(id===generation)error.value=(e as Error).message}finally{if(id===generation)busy.value=false}
}
const fmt=(v:any)=>Number(v).toFixed(2)
</script>
<template><el-dialog :model-value="!!row" title="计算收入 · 预计毛利" width="620px" :close-on-click-modal="false" @close="generation++;emit('close')"><p class="income-identity">{{row?.sku}}</p><p class="muted">{{row?.store}} · {{row?.marketplace}} · FBA · 每个销售单位 · 买家运费按0</p><div class="income-input"><el-input v-model="price" aria-label="测算售价" placeholder="测算售价" :disabled="busy" @input="result=null"><template #prepend>销售收入</template><template #append>{{result?.currency||row?.pricing.currency||'站点币种'}}</template></el-input><el-button type="primary" :loading="busy" @click="calculate(true)">计算</el-button></div><p class="muted">首次打开读取最新普通买家报价；修改此处售价仅用于测算。</p><el-alert v-if="error" :title="error" type="error" :closable="false"/><div v-if="busy" class="income-loading">正在读取亚马逊费用预估…</div><template v-if="result"><div class="income-result"><div class="income-total" :class="{negative:Number(result.gross_profit)<0}"><span>预计毛利</span><strong>{{result.currency}} {{fmt(result.gross_profit)}}</strong><small>预计毛利率 {{result.gross_margin}}%</small></div><dl class="income-breakdown"><div><dt>销售佣金</dt><dd>{{fmt(result.referral_fee)}} {{result.currency}}</dd></div><div><dt>FBA费用</dt><dd>{{fmt(result.fba_fee)}} {{result.currency}}</dd></div><div v-if="Number(result.other_amazon_fees)!==0"><dt>其他亚马逊费用</dt><dd>{{fmt(result.other_amazon_fees)}} {{result.currency}}</dd></div><div><dt>增值税预估 <small>含税售价 ÷ 1.20 × 20%</small></dt><dd>{{fmt(result.vat)}} {{result.currency}}</dd></div><div><dt>采购成本 <el-tag v-if="result.purchase_missing" type="warning" size="small">没有记录 · 按0</el-tag><small v-else>人民币 {{result.purchase_cost_cny}}</small></dt><dd>{{fmt(result.purchase_cost)}} {{result.currency}}</dd></div><div><dt>头程运费 <el-tag v-if="result.freight_missing" type="warning" size="small">没有记录 · 按0</el-tag></dt><dd>{{fmt(result.freight_cost)}} {{result.currency}}</dd></div></dl></div><p class="income-note">{{result.note}}</p><p v-if="result.purchase_missing||result.freight_missing" class="income-warning">成本记录不完整，当前毛利可能偏高。</p><p class="muted">{{result.product_name?'关联商品：'+result.product_name:'尚未关联本地商品'}}<br>费用估算时间：{{result.fee_time?new Date(result.fee_time).toLocaleString('zh-CN'):'未返回'}}{{result.cached?'（10分钟内缓存）':''}}<template v-if="!result.purchase_missing"><br>采购成本换算汇率日期：{{result.fx_date||'无需换汇'}}{{result.fx_stale?' · 缓存待刷新':''}}</template></p></template><template #footer><el-button @click="emit('close')">关闭</el-button></template></el-dialog></template>
<style scoped>.income-identity{font-weight:600;overflow-wrap:anywhere}.muted,.income-note{font-size:12px;color:#7f9187;line-height:1.8}.income-input{display:flex;gap:12px;margin:20px 0 8px}.income-total{padding:20px;background:#edf6f0;border-radius:8px;color:#216850;display:flex;align-items:center;gap:14px;flex-wrap:wrap}.income-total strong{font-size:25px}.income-total.negative{background:#fff1ef;color:#bd4d40}.income-total small{margin-left:auto}.income-breakdown{margin:16px 0}.income-breakdown>div{display:flex;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid #edf1ee;font-size:13px}.income-breakdown dt{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.income-breakdown dd{margin:0;white-space:nowrap;font-variant-numeric:tabular-nums}.income-breakdown small{color:#8b9a91}.income-warning{font-size:12px;color:#ad772e}.income-loading{text-align:center;padding:36px;color:#83958b}</style>
